/* From Uiverse.io by Yaya12085 - Tags: form, input, sign-up, register */
.__UIV_SCOPE__ .form {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-width: 350px;
  background-color: #fff;
  padding: 20px;
  border-radius: 20px;
  position: relative;
}

.__UIV_SCOPE__ .title {
  font-size: 28px;
  color: royalblue;
  font-weight: 600;
  letter-spacing: -1px;
  position: relative;
  display: flex;
  align-items: center;
  padding-left: 30px;
}

.__UIV_SCOPE__ .title::before,.__UIV_SCOPE__ .title::after {
  position: absolute;
  content: "";
  height: 16px;
  width: 16px;
  border-radius: 50%;
  left: 0px;
  background-color: royalblue;
}

.__UIV_SCOPE__ .title::before {
  width: 18px;
  height: 18px;
  background-color: royalblue;
}

.__UIV_SCOPE__ .title::after {
  width: 18px;
  height: 18px;
  animation: pulse 1s linear infinite;
}

.__UIV_SCOPE__ .message, .__UIV_SCOPE__ .signin {
  color: rgba(88, 87, 87, 0.822);
  font-size: 14px;
}

.__UIV_SCOPE__ .signin {
  text-align: center;
}

.__UIV_SCOPE__ .signin a {
  color: royalblue;
}

.__UIV_SCOPE__ .signin a:hover {
  text-decoration: underline royalblue;
}

.__UIV_SCOPE__ .flex {
  display: flex;
  width: 100%;
  gap: 6px;
}

.__UIV_SCOPE__ .form label {
  position: relative;
}

.__UIV_SCOPE__ .form label .input {
  width: 100%;
  padding: 10px 10px 20px 10px;
  outline: 0;
  border: 1px solid rgba(105, 105, 105, 0.397);
  border-radius: 10px;
}

.__UIV_SCOPE__ .form label .input + span {
  position: absolute;
  left: 10px;
  top: 15px;
  color: grey;
  font-size: 0.9em;
  cursor: text;
  transition: 0.3s ease;
}

.__UIV_SCOPE__ .form label .input:placeholder-shown + span {
  top: 15px;
  font-size: 0.9em;
}

.__UIV_SCOPE__ .form label .input:focus + span,.__UIV_SCOPE__ .form label .input:valid + span {
  top: 30px;
  font-size: 0.7em;
  font-weight: 600;
}

.__UIV_SCOPE__ .form label .input:valid + span {
  color: green;
}

.__UIV_SCOPE__ .submit {
  border: none;
  outline: none;
  background-color: royalblue;
  padding: 10px;
  border-radius: 10px;
  color: #fff;
  font-size: 16px;
  transform: .3s ease;
}

.__UIV_SCOPE__ .submit:hover {
  background-color: rgb(56, 90, 194);
}

@keyframes pulse {
  from {
    transform: scale(0.9);
    opacity: 1;
  }

  to {
    transform: scale(1.8);
    opacity: 0;
  }
}
